package kvm

import "github.com/jetkvm/kvm/internal/native"

// EDIDPreset is an EDID the device offers by name. The list lives here so the
// UI does not carry its own copy and the device decides what it advertises.
type EDIDPreset struct {
	Name string `json:"name"`
	EDID string `json:"edid"`
}

var edidPresets = []EDIDPreset{
	{Name: "JetKVM Default", EDID: native.DefaultEDID},
	{Name: "Acer B246WL, 1920x1200", EDID: ""},
	{Name: "ASUS PA248QV, 1920x1200", EDID: ""},
	{Name: "DELL D2721H, 1920x1080", EDID: ""},
	{Name: "DELL IDRAC EDID, 1280x1024", EDID: "00FFFFFFFFFFFF0010AC0100020000000111010380221BFF0A00000000000000000000ADCE0781800101010101010101010101010101000000FF0030303030303030303030303030000000FF0030303030303030303030303030000000FD00384C1F530B000A000000000000000000FC0044454C4C2049445241430A2020000A"},
}

func rpcGetEDIDPresets() ([]EDIDPreset, error) {
	return edidPresets, nil
}
